def add_default_ratios(apps, schema_editor):
    """Every organisation's settings get the ratios /review showed until now, so nothing changes until edited."""
    Settings = apps.get_model("review", "ReviewSettings")
    Ratio = apps.get_model("review", "ReviewRatio")
    for settings in Settings.objects.all():
        Ratio.objects.bulk_create([Ratio(organisation_id=settings.organisation_id, settings=settings, name=name,
                                         formula=formula, order=i) for i, (name, formula) in enumerate(DEFAULTS, 1)])


